import React, {useContext, useEffect, useRef, useState} from "react";
import LabShell from "./LabShell";
import StyleContext from "../contexts/StyleContext";

const scenes = [
  {id: "satellite", label: "Satellite incident", icon: "🛰️"},
  {id: "astronaut", label: "EVA surprise", icon: "🧑‍🚀"},
  {id: "rocket", label: "Launch day", icon: "🚀"}
];

const presets = [
  ["WHEN THE SIMULATION CONVERGES", "BUT ONLY WITH DRAG TURNED OFF"],
  ["MISSION CONTROL: ONE SMALL CHANGE", "THE CHANGE:"],
  ["I SAID NOMINAL", "I DID NOT SAY COMFORTABLE"],
  ["DEPLOYMENT FRIDAY?", "BOLD TRAJECTORY, FLIGHT"],
  ["THE UNIT TEST PASSED", "THE SPACECRAFT HAD OTHER PLANS"]
];

const starField = Array.from({length: 72}, (_, index) => ({
  x: (index * 127 + 31) % 900,
  y: (index * 71 + 19) % 600,
  r: index % 9 === 0 ? 2 : 1
}));

function drawFittedText(context, text, y, maxWidth) {
  let size = 54;
  context.font = `900 ${size}px Montserrat, sans-serif`;
  while (context.measureText(text).width > maxWidth && size > 25) {
    size -= 2;
    context.font = `900 ${size}px Montserrat, sans-serif`;
  }
  context.lineWidth = Math.max(5, size / 8);
  context.strokeStyle = "#02040a";
  context.textAlign = "center";
  context.strokeText(text, 450, y);
  context.fillStyle = "#ffffff";
  context.fillText(text, 450, y);
}

export default function MemeGenerator() {
  const {isDark} = useContext(StyleContext);
  const canvasRef = useRef(null);
  const [topText, setTopText] = useState("WHEN THE SIMULATION CONVERGES");
  const [bottomText, setBottomText] = useState("BUT ONLY WITH DRAG TURNED OFF");
  const [scene, setScene] = useState("satellite");

  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas.getContext("2d");
    const gradient = context.createLinearGradient(0, 0, 900, 600);
    gradient.addColorStop(0, isDark ? "#020510" : "#0b2352");
    gradient.addColorStop(.58, "#101c4a");
    gradient.addColorStop(1, "#35135b");
    context.fillStyle = gradient;
    context.fillRect(0, 0, 900, 600);

    context.fillStyle = "rgba(225,243,255,.78)";
    starField.forEach(star => {
      context.beginPath();
      context.arc(star.x, star.y, star.r, 0, Math.PI * 2);
      context.fill();
    });

    const glow = context.createRadialGradient(735, 510, 8, 735, 510, 215);
    glow.addColorStop(0, "rgba(68,184,255,.72)");
    glow.addColorStop(.45, "rgba(31,96,205,.65)");
    glow.addColorStop(1, "rgba(6,20,61,0)");
    context.fillStyle = glow;
    context.fillRect(500, 280, 400, 320);
    context.fillStyle = "#174891";
    context.beginPath();
    context.arc(775, 650, 230, 0, Math.PI * 2);
    context.fill();
    context.fillStyle = "rgba(75,202,172,.58)";
    context.beginPath();
    context.ellipse(720, 500, 82, 31, -.4, 0, Math.PI * 2);
    context.ellipse(820, 475, 58, 26, .5, 0, Math.PI * 2);
    context.fill();

    const selected = scenes.find(item => item.id === scene);
    context.textAlign = "center";
    context.font = "170px 'Segoe UI Emoji', sans-serif";
    context.shadowColor = "rgba(90,200,255,.65)";
    context.shadowBlur = 30;
    context.fillText(selected.icon, 450, 375);
    context.shadowBlur = 0;

    drawFittedText(context, topText.toUpperCase() || "TOP TEXT", 72, 820);
    drawFittedText(context, bottomText.toUpperCase() || "BOTTOM TEXT", 565, 820);

    context.textAlign = "left";
    context.font = "700 13px Montserrat, sans-serif";
    context.fillStyle = "rgba(201,220,255,.65)";
    context.fillText("AVIK'S MISSION LAB", 24, 582);
  }, [topText, bottomText, scene, isDark]);

  const randomize = () => {
    const preset = presets[Math.floor(Math.random() * presets.length)];
    const nextScene = scenes[Math.floor(Math.random() * scenes.length)];
    setTopText(preset[0]);
    setBottomText(preset[1]);
    setScene(nextScene.id);
  };

  const download = () => {
    const link = document.createElement("a");
    link.download = "mission-control-meme.png";
    link.href = canvasRef.current.toDataURL("image/png");
    link.click();
  };

  return (
    <LabShell
      eyebrow="MISSION LAB / 02"
      title="Space Meme Generator"
      intro="Select a mission mishap, add your own flight-loop commentary, and export something the group chat deserves."
    >
      <section className="meme-layout">
        <div className="meme-canvas-wrap">
          <canvas ref={canvasRef} width="900" height="600" aria-label="Generated space meme preview" />
        </div>
        <aside className="meme-controls">
          <div className="control-group">
            <label htmlFor="top-text">TOP TRANSMISSION</label>
            <input id="top-text" maxLength="54" value={topText} onChange={event => setTopText(event.target.value)} />
          </div>
          <div className="control-group">
            <label htmlFor="bottom-text">BOTTOM TRANSMISSION</label>
            <input id="bottom-text" maxLength="54" value={bottomText} onChange={event => setBottomText(event.target.value)} />
          </div>
          <div className="control-group">
            <span>SELECT SCENE</span>
            <div className="scene-options">
              {scenes.map(item => (
                <button
                  className={scene === item.id ? "is-selected" : ""}
                  key={item.id}
                  onClick={() => setScene(item.id)}
                  aria-pressed={scene === item.id}
                >
                  <b>{item.icon}</b>{item.label}
                </button>
              ))}
            </div>
          </div>
          <div className="meme-actions">
            <button className="secondary-action" onClick={randomize}>Surprise me</button>
            <button className="primary-action" onClick={download}>Download PNG ↗</button>
          </div>
        </aside>
      </section>
    </LabShell>
  );
}
